// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 t, address actor) public {
        vm.assume(actor != address(0));
        t = bound(t, 1, 1e12);
        uint256 T = block.timestamp + t;
        vm.warp(T);
        uint256 amount = 10 ether;
        vm.deal(actor, 2 * amount);

        // first call: succeeds in both versions
        vm.prank(actor);
        c.fallback{value: amount}();

        // second call at the SAME timestamp: reference stores pastBlockTime = T+1,
        // so require(block.timestamp > pastBlockTime) fails here and it reverts;
        // the mutant never advances pastBlockTime and this call succeeds.
        vm.prank(actor);
        bool ok;
        try c.fallback{value: amount, gas: 100000}() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "a second call at the same timestamp must revert");
    }
}

