        ts = bound(ts, block.timestamp + 1, type(uint256).max - 2);
        vm.assume(actor != address(0) && actor != address(c));
        vm.warp(ts);
        // avoid the payout branch so the call cannot revert
        vm.roll(block.number + (15 - block.number % 15) + 1);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        c.fallback{value: 10 ether}();
        assertTrue(c.pastBlockTime() == block.timestamp + 1);
    }
}

