pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 t1, uint256 b1, uint256 b2, address actor) public {
        t1 = bound(t1, 1, type(uint256).max / 2);
        vm.assume(actor != address(c) && actor.code.length == 0);

        // first call at timestamp t1 must succeed for any admissible input
        vm.warp(t1);
        vm.roll(bound(b1, 0, type(uint64).max));
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);

        // general rule: a second call exactly one second later still succeeds,
        // since pastBlockTime was set to t1+1 and the require needs > pastBlockTime.
        vm.warp(t1 + 1);
        vm.roll(bound(b2, 0, type(uint64).max));
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok2);
    }
}

