pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 t, uint256 n, address actor) public {
        vm.assume(actor != address(c) && actor != address(this));
        t = bound(t, 1, type(uint256).max / 2);
        n = bound(n, 0, 1_000_000);
        if (n % 15 == 0) n += 1; // keep away from the payout branch so balance stays observable

        vm.roll(n);
        vm.warp(t);

        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        if (!ok1) return;

        // second deposit at the SAME block timestamp must be rejected
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok2,) = address(c).call{value: 10 ether}("");

        assertTrue(ok1 && !ok2 && address(c).balance == 10 ether);
    }
