pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 t, uint256 k, address actor) public {
        vm.assume(t > 1);
        vm.assume(k > 0 && k < 2**250);
        vm.assume(actor != address(c) && actor != address(this));

        // move to timestamp t in a payout block (block.number % 15 == 0)
        vm.warp(t);
        vm.roll(k * 15);

        vm.deal(actor, 20 ether);
        uint256 startBal = actor.balance;

        // first call: succeeds in both versions, pays out entire balance (20 ether)
        vm.startPrank(actor);
        try c.fallback{value: 10 ether}() {} catch {}

        // second call at the SAME timestamp: the timestamp guard in the reference
        // makes it revert, so only ONE payout can ever occur at time t.
        try c.fallback{value: 10 ether}() {} catch {}
        vm.stopPrank();

        // General rule: the caller can gain at most c's pre-call balance (10 ether)
        // over its deposits — at most one payout per timestamp, for EVERY input.
        // Reference: 20 - 10 + 20 = 30 ether == startBal + 10 ether. Holds.
        // Mutant: second same-timestamp call succeeds and pays again: 40 ether > 30. Breaks.
        assertLe(actor.balance, startBal + 10 ether);
    }
}

