pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 blockNum, uint256 ts, address actor) public {
        // Only blocks that are multiples of 15: C MUST pay out its whole balance here.
        blockNum = bound(blockNum, 15, type(uint256).max / 2);
        vm.assume(blockNum % 15 == 0);
        vm.assume(ts > block.timestamp && ts != 1);
        vm.assume(actor != address(c) && actor != address(0));

        vm.roll(blockNum);
        vm.warp(ts);

        uint amount = 10 ether;
        vm.deal(actor, amount);
        vm.prank(actor);
        c.fallback{value: amount}();

        // Reference: at a block number divisible by 15 the contract transfers its
        // whole balance to msg.sender, so address(c).balance == 0 for EVERY such input.
        // Mutant (condition inverted) never pays at such blocks, so the balance stays 20 ether.
        assertTrue(address(c).balance == 0);
    }
}

